'use strict';
const express = require('express');
const helmet = require('helmet');
const argon2 = require('argon2');
const { MongoClient, ObjectId } = require('mongodb');
const crypto = require('node:crypto');

const app = express();
app.disable('x-powered-by');
app.set('trust proxy', 1);
app.use(helmet({ contentSecurityPolicy: false, crossOriginEmbedderPolicy: false }));
app.use(express.json({ limit: '128kb' }));
app.use((req,res,next)=>{ res.set('Cache-Control','no-store'); next(); });
app.use((req,_res,next)=>{req.cookies={};for(const p of (req.headers.cookie||'').split(';')){const i=p.indexOf('=');if(i>0)req.cookies[p.slice(0,i).trim()]=decodeURIComponent(p.slice(i+1).trim())}next()});
let clientPromise;
function db() {
  if (!process.env.MONGODB_URI) throw Object.assign(new Error('Database is not configured. Set MONGODB_URI and DB_NAME in the deployment environment.'), { status: 503 });
  if (!clientPromise) { const c = new MongoClient(process.env.MONGODB_URI, { serverSelectionTimeoutMS: 8000, maxPoolSize: 10 }); clientPromise = c.connect().catch(e => { clientPromise = null; throw e; }); }
  return clientPromise.then(c => c.db(process.env.DB_NAME || 'pb_seva'));
}
const oid = id => { if (!ObjectId.isValid(String(id))) throw Object.assign(new Error('Invalid identifier'),{status:400}); return new ObjectId(String(id)); };
