app.use(async(req,res,next)=>{if(!req.path.startsWith('/api/'))return next();try{req.db=await db();await initDb();next()}catch(e){next(e)}});
app.use('/api',async(req,res,next)=>{if(!['POST','PATCH','DELETE','PUT'].includes(req.method)||req.path.startsWith('/auth/'))return next();try{if(!req.cookies?.sid)return next();const s=await req.db.collection('sessions').findOne({tokenHash:sha(req.cookies.sid)}),csrf=req.headers['x-csrf-token'];if(!s||!csrf||sha(csrf)!==s.csrfHash)return res.status(403).json({error:'CSRF validation failed.'});next()}catch(e){next(e)}});
async function current(req){const raw=req.cookies?.sid||req.headers.authorization?.replace(/^Bearer /,'');if(!raw)return null;const d=req.db||await db(),s=await d.collection('sessions').findOne({tokenHash:sha(raw),expiresAt:{$gt:new Date()}});if(!s)return null;const u=await d.collection('users').findOne({_id:s.userId,status:'active'},{projection:{passwordHash:0}});return u?{...u,sessionId:s._id}:null}
async function auth(req,res,next){try{req.user=await current(req);if(!req.user)return res.status(401).json({error:'Sign in required'});next()}catch(e){next(e)}}
async function admin(req,res,next){try{req.user=await current(req);if(!req.user)return res.status(401).json({error:'Sign in required'});if(req.user.role!=='admin')return res.status(403).json({error:'Administrator access required'});next()}catch(e){next(e)}}
