app.post('/api/wallet/topup-requests',auth,async(req,res,next)=>{try{const amount=Number(req.body?.amount),note=clean(req.body?.note);if(!Number.isInteger(amount)||amount<1||amount>50000||note.length>120)return res.status(400).json({error:'Enter a whole-rupee request from ₹1 to ₹50,000.'});const doc={userId:req.user._id,amountPaise:amount*100,note,status:'pending',reference:'TU-'+random(9).toUpperCase(),createdAt:new Date()};await req.db.collection('topupRequests').insertOne(doc);res.status(201).json({request:{reference:doc.reference,status:doc.status}})}catch(e){next(e)}});
app.post('/api/applications',auth,async(req,res,next)=>{const d=req.db;try{const service=await d.collection('services').findOne({_id:oid(req.body?.serviceId),status:'active'});if(!service)return res.status(404).json({error:'Service is unavailable.'});const answers=req.body?.answers||{};if(typeof answers!=='object'||Array.isArray(answers))return res.status(400).json({error:'Invalid application answers.'});for(const f of service.fields||[]){const value=answers[f.key||f.label];if(f.required&&!clean(value))return res.status(400).json({error:f.label+' is required.'});if(value&&String(value).length>(f.maxLength||1000))return res.status(400).json({error:f.label+' is too long.'});if(f.type==='email'&&value&&!/^\S+@\S+\.\S+$/.test(value))return res.status(400).json({error:f.label+' must be a valid email.'})}const idem=clean(req.body?.idempotencyKey);if(!/^[\w-]{16,100}$/.test(idem))return res.status(400).json({error:'A valid idempotency key is required.'});const ref='PB-'+new Date().getUTCFullYear()+'-'+random(5).toUpperCase(),txref='WT-'+random(9).toUpperCase(),now=new Date(),amount=service.pricePaise;if(!Number.isSafeInteger(amount)||amount<0)return res.status(400).json({error:'Service price is invalid.'});const appDoc={reference:ref,userId:req.user._id,serviceId:service._id,serviceName:service.name,pricePaise:amount,serviceSnapshot:{name:service.name,pricePaise:amount,fields:service.fields,documents:service.documents},answers,documents:[],status:'Submitted',paymentStatus:amount?'paid':'not_required',createdAt:now,updatedAt:now,audit:[{status:'Submitted',at:now,actorId:req.user._id}]};const session=clientPromise?await (await clientPromise).startSession():null;if(!session)throw new Error('Database session unavailable');try{await session.withTransaction(async()=>{const prior=await d.collection('walletTransactions').findOne({idempotencyKey:idem},{session});if(prior){const existing=await d.collection('applications').findOne({_id:prior.applicationId},{session});if(existing){appDoc._id=existing._id;return}}const w=await d.collection('walletAccounts').findOne({userId:req.user._id},{session});const bal=w?.balancePaise||0;if(bal<amount)throw Object.assign(new Error('Insufficient service-credit balance.'),{status:402});const inserted=await d.collection('applications').insertOne(appDoc,{session});const upd=await d.collection('walletAccounts').updateOne({userId:req.user._id,balancePaise:bal},{$set:{balancePaise:bal-amount,updatedAt:now}},{session});if(upd.modifiedCount!==1)throw Object.assign(new Error('Wallet changed. Please retry.'),{status:409});if(amount)await d.collection('walletTransactions').insertOne({reference:txref,userId:req.user._id,type:'debit',amountPaise:amount,balanceBeforePaise:bal,balanceAfterPaise:bal-amount,reason:'Service application: '+service.name,applicationId:inserted.insertedId,applicationReference:ref,actorId:req.user._id,idempotencyKey:idem,createdAt:now},{session});appDoc._id=inserted.insertedId})}finally{await session.endSession()}await audit(d,req.user,'application.submit',ref,{serviceId:String(service._id),amountPaise:amount});res.status(201).json({application:{id:String(appDoc._id),reference:ref},transaction:{reference:txref}})}catch(e){if(e.code===11000){const t=await d.collection('walletTransactions').findOne({idempotencyKey:clean(req.body?.idempotencyKey)});if(t)return res.json({application:{reference:t.applicationReference},transaction:{reference:t.reference}})}next(e)}});
