app.get('/api/applications/:id/receipt',auth,async(req,res,next)=>{try{const a=await req.db.collection('applications').findOne({_id:oid(req.params.id),userId:req.user._id},{projection:{reference:1,serviceName:1,status:1,pricePaise:1,createdAt:1}});if(!a)return res.status(404).json({error:'Application not found'});res.json({receipt:a})}catch(e){next(e)}});
const paged=async(col,filter={},limit=100)=>col.find(filter).sort({createdAt:-1}).limit(limit).toArray();
app.get('/api/admin/dashboard',admin,async(req,res,next)=>{try{const d=req.db,A=d.collection('applications'),stats={customers:await d.collection('users').countDocuments({role:'customer'}),activeServices:await d.collection('services').countDocuments({status:'active'}),applications:await A.countDocuments(),pendingApplications:await A.countDocuments({status:{$in:['Submitted','Under Review','Documents Required','In Progress']}}),completedApplications:await A.countDocuments({status:'Completed'}),cancelledApplications:await A.countDocuments({status:'Cancelled'}),pendingTopups:await d.collection('topupRequests').countDocuments({status:'pending'})};res.json({stats,recentApplications:await A.find().sort({createdAt:-1}).limit(8).project({reference:1,serviceName:1,status:1,createdAt:1}).toArray()})}catch(e){next(e)}});
app.get('/api/admin/services',admin,async(req,res,next)=>{try{res.json({items:await paged(req.db.collection('services'),{},200)})}catch(e){next(e)}});
app.post('/api/admin/services',admin,async(req,res,next)=>{try{const x=validateService(req.body);if(!x)return res.status(400).json({error:'Service name, slug, valid price and status are required.'});x.createdAt=x.updatedAt=new Date();const r=await req.db.collection('services').insertOne(x);await audit(req.db,req.user,'service.create',String(r.insertedId));res.status(201).json({id:String(r.insertedId)})}catch(e){if(e.code===11000)return res.status(409).json({error:'Service slug already exists.'});next(e)}});
app.patch('/api/admin/services/:id',admin,async(req,res,next)=>{try{const x=validateService(req.body);if(!x)return res.status(400).json({error:'Invalid service data.'});delete x.createdAt;x.updatedAt=new Date();await req.db.collection('services').updateOne({_id:oid(req.params.id)},{$set:x});await audit(req.db,req.user,'service.update',req.params.id);res.json({ok:true})}catch(e){next(e)}});
app.delete('/api/admin/services/:id',admin,async(req,res,next)=>{try{await req.db.collection('services').updateOne({_id:oid(req.params.id)},{$set:{status:'archived',updatedAt:new Date()}});await audit(req.db,req.user,'service.archive',req.params.id);res.json({ok:true})}catch(e){next(e)}});
function validateService(b){if(!b||clean(b.name).length<2||clean(b.name).length>120||!/^[a-z0-9]+(?:-[a-z0-9]+)*$/.test(clean(b.slug))||!Number.isSafeInteger(Number(b.pricePaise))||Number(b.pricePaise)<0||!['active','draft','archived'].includes(b.status))return null;return {name:clean(b.name),slug:clean(b.slug),description:clean(b.description).slice(0,3000),categoryId:clean(b.categoryId),categoryName:clean(b.categoryName),pricePaise:Number(b.pricePaise),priceUnit:['per page','fixed'].includes(b.priceUnit)?b.priceUnit:'fixed',status:b.status,featured:!!b.featured,icon:clean(b.icon).slice(0,12),aliases:Array.isArray(b.aliases)?b.aliases.slice(0,30).map(x=>clean(x).slice(0,80)):[],keywords:Array.isArray(b.keywords)?b.keywords.slice(0,50).map(x=>clean(x).slice(0,80)):[],documents:Array.isArray(b.documents)?b.documents.slice(0,30).map(x=>({name:clean(x.name).slice(0,120),required:!!x.required})):[],fields:Array.isArray(b.fields)?b.fields.slice(0,30).map(x=>({key:clean(x.key).slice(0,80),label:clean(x.label).slice(0,120),help:clean(x.help).slice(0,300),type:['text','email','mobile','date','select','checkbox','textarea'].includes(x.type)?x.type:'text',required:!!x.required,maxLength:Math.min(5000,Math.max(1,Number(x.maxLength)||500)),options:Array.isArray(x.options)?x.options.slice(0,50).map(o=>clean(o).slice(0,100)):[]})):[],processingTime:clean(b.processingTime).slice(0,120),consentText:clean(b.consentText).slice(0,1000)}}
app.get('/api/admin/users',admin,async(req,res,next)=>{try{const users=await paged(req.db.collection('users'),{role:'customer'},200),items=await Promise.all(users.map(async u=>{const [w,n]=await Promise.all([req.db.collection('walletAccounts').findOne({userId:u._id}),req.db.collection('applications').countDocuments({userId:u._id})]);return {id:String(u._id),name:u.name,email:u.email,mobileMasked:u.mobile?u.mobile.replace(/.(?=.{4})/g,'•'):'',status:u.status,createdAt:u.createdAt,balancePaise:w?.balancePaise||0,applicationCount:n}}));res.json({items})}catch(e){next(e)}});
app.get('/api/admin/applications',admin,async(req,res,next)=>{try{res.json({items:await paged(req.db.collection('applications'),{},200)})}catch(e){next(e)}});
const transitions={Submitted:['Under Review','Cancelled'], 'Under Review':['Documents Required','In Progress','Rejected','Cancelled'], 'Documents Required':['Under Review','In Progress','Rejected','Cancelled'], 'In Progress':['Completed','Documents Required','Rejected','Cancelled'],Completed:[],Rejected:[],Cancelled:[]};
app.patch('/api/admin/applications/:id/status',admin,async(req,res,next)=>{try{const id=oid(req.params.id),status=clean(req.body?.status),reason=clean(req.body?.reason),a=await req.db.collection('applications').findOne({_id:id});if(!a)return res.status(404).json({error:'Application not found'});if(!(transitions[a.status]||[]).includes(status))return res.status(409).json({error:'Invalid status transition.'});if(['Rejected','Cancelled'].includes(status)&&reason.length<3)return res.status(400).json({error:'A reason is required.'});const item={status,reason,at:new Date(),actorId:req.user._id};await req.db.collection('applications').updateOne({_id:id,status:a.status},{$set:{status,updatedAt:item.at},$push:{audit:item}});await audit(req.db,req.user,'application.status',a.reference,{status,reason});res.json({ok:true})}catch(e){next(e)}});
app.get('/api/admin/wallet/transactions',admin,async(req,res,next)=>{try{res.json({items:await paged(req.db.collection('walletTransactions'),{},200)})}catch(e){next(e)}});
app.post('/api/admin/wallet/adjustments',admin,async(req,res,next)=>{const d=req.db;try{const userId=oid(req.body?.userId),amount=Number(req.body?.amountPaise),type=clean(req.body?.type),reason=clean(req.body?.reason);if(!Number.isSafeInteger(amount)||amount<1||amount>100000000||!['credit','debit'].includes(type)||reason.length<3||reason.length>500)return res.status(400).json({error:'Valid amount, adjustment type and reason are required.'});const session=await (await clientPromise).startSession(),reference='AD-'+random(9).toUpperCase();try{await session.withTransaction(async()=>{const w=await d.collection('walletAccounts').findOne({userId},{session});if(!w)throw Object.assign(new Error('Wallet not found'),{status:404});const next=w.balancePaise+(type==='credit'?amount:-amount);if(next<0)throw Object.assign(new Error('Debit exceeds available balance.'),{status:409});await d.collection('walletAccounts').updateOne({_id:w._id,balancePaise:w.balancePaise},{$set:{balancePaise:next,updatedAt:new Date()}},{session});await d.collection('walletTransactions').insertOne({reference,userId,type,amountPaise:amount,balanceBeforePaise:w.balancePaise,balanceAfterPaise:next,reason,actorId:req.user._id,createdAt:new Date()},{session})})}finally{await session.endSession()}await audit(d,req.user,'wallet.adjustment',reference,{userId:String(userId),amountPaise:amount,type,reason});res.status(201).json({reference})}catch(e){next(e)}});
app.get('/api/admin/topup-requests',admin,async(req,res,next)=>{try{let items=await paged(req.db.collection('topupRequests'),{},200);items=await Promise.all(items.map(async x=>({...x,customerName:(await req.db.collection('users').findOne({_id:x.userId},{projection:{name:1}}))?.name||'Customer'})));res.json({items})}catch(e){next(e)}});
app.patch('/api/admin/topup-requests/:id',admin,async(req,res,next)=>{const d=req.db;try{const id=oid(req.params.id),status=clean(req.body?.status),reason=clean(req.body?.reason);if(!['approved','rejected'].includes(status)||reason.length<3)return res.status(400).json({error:'Choose approve or reject and provide a reason.'});let result;const session=await (await clientPromise).startSession();try{await session.withTransaction(async()=>{const t=await d.collection('topupRequests').findOne({_id:id,status:'pending'},{session});if(!t)throw Object.assign(new Error('Request is no longer pending.'),{status:409});await d.collection('topupRequests').updateOne({_id:id,status:'pending'},{$set:{status,reviewedAt:new Date(),reviewedBy:req.user._id,reviewReason:reason}},{session});if(status==='approved'){let w=await d.collection('walletAccounts').findOne({userId:t.userId},{session});if(!w){await d.collection('walletAccounts').insertOne({userId:t.userId,balancePaise:0,updatedAt:new Date()},{session});w=await d.collection('walletAccounts').findOne({userId:t.userId},{session})}const next=w.balancePaise+t.amountPaise;await d.collection('walletAccounts').updateOne({_id:w._id,balancePaise:w.balancePaise},{$set:{balancePaise:next,updatedAt:new Date()}},{session});const ref='TU-'+random(9).toUpperCase();await d.collection('walletTransactions').insertOne({reference:ref,userId:t.userId,type:'credit',amountPaise:t.amountPaise,balanceBeforePaise:w.balancePaise,balanceAfterPaise:next,reason:'Verified top-up request '+t.reference,topupRequestId:id,actorId:req.user._id,createdAt:new Date()},{session});result=ref}})}finally{await session.endSession()}await audit(d,req.user,'topup.review',req.params.id,{status,reason});res.json({ok:true,transactionReference:result})}catch(e){next(e)}});
app.get('/api/admin/settings',admin,async(req,res,next)=>{try{res.json({settings:await req.db.collection('settings').findOne({_id:'website'})||{_id:'website',brandName:'PB Digital Seva Kendra',tagline:'Aapki Har Digital Seva, Ek Hi Jagah',supportMessage:'Contact our team for support.'}})}catch(e){next(e)}});
app.patch('/api/admin/settings',admin,async(req,res,next)=>{try{const allow=['brandName','tagline','supportMessage','contactNumber','supportEmail','whatsappUrl','address','openingHours','announcement','heroTitle','heroText','themeColors','footerLinks','privacyPolicy','terms','serviceChargeDisclaimer','maintenanceMode','topupInstructions','paymentMethods'];const set={updatedAt:new Date()};for(const k of allow)if(req.body?.[k]!==undefined){const v=req.body[k];if(typeof v==='string')set[k]=v.slice(0,5000);else if(['boolean'].includes(typeof v)||Array.isArray(v)||typeof v==='object')set[k]=v}await req.db.collection('settings').updateOne({_id:'website'},{$set:set},{upsert:true});await audit(req.db,req.user,'settings.update','website');res.json({ok:true})}catch(e){next(e)}});
app.get('/api/admin/audit-logs',admin,async(req,res,next)=>{try{res.json({items:await paged(req.db.collection('auditLogs'),{},200)})}catch(e){next(e)}});
app.get('/api/admin/categories',admin,async(req,res,next)=>{try{res.json({items:await req.db.collection('categories').find().sort({order:1}).toArray()})}catch(e){next(e)}});
app.post('/api/admin/categories',admin,async(req,res,next)=>{try{const name=clean(req.body?.name),slug=clean(req.body?.slug);if(name.length<2||name.length>100||!/^[a-z0-9-]+$/.test(slug))return res.status(400).json({error:'Valid category name and slug required.'});const r=await req.db.collection('categories').insertOne({name,slug,icon:clean(req.body.icon).slice(0,12),active:true,order:Number(req.body.order)||0,createdAt:new Date()});await audit(req.db,req.user,'category.create',String(r.insertedId));res.status(201).json({id:String(r.insertedId)})}catch(e){next(e)}});
app.get('/api/admin/users/:id',admin,async(req,res,next)=>{try{const user=await req.db.collection('users').findOne({_id:oid(req.params.id)},{projection:{passwordHash:0}});if(!user)return res.status(404).json({error:'Customer not found'});const [wallet,applications,transactions]=await Promise.all([req.db.collection('walletAccounts').findOne({userId:user._id}),paged(req.db.collection('applications'),{userId:user._id}),paged(req.db.collection('walletTransactions'),{userId:user._id})]);res.json({user,wallet,applications,transactions})}catch(e){next(e)}});
app.use((err,_req,res,_next)=>{const status=err.status|| (err.name==='BSONError'?400:500);if(status>=500)console.error('Request failed:',err.name||'Error');res.status(status).json({error:status>=500?'The request could not be completed. Please try again.':err.message||'Invalid request.'})});
app.use((_req,res)=>res.status(404).json({error:'Not found'}));
module.exports=app;
if(require.main===module){const port=Number(process.env.PORT||3000);app.listen(port,()=>console.log('Listening on '+port))}
